import ipaddress
def publish(request,namespace,name,port_name,addresses):
    if not isinstance(addresses,list) or not addresses or any(not isinstance(v,str) for v in addresses):raise ValueError('explicit literal addresses required')
    hosts=[ipaddress.ip_address(v) for v in addresses]
    status,value=request('GET','/api/v1/namespaces/'+namespace+'/services/'+name)
    if status!=200:raise RuntimeError('approved Service read failed')
    spec=value['spec']
    if spec.get('type')!='NodePort':raise ValueError('NodePort Service required')
    matches=[row for row in spec['ports'] if row.get('name')==port_name and row.get('protocol','TCP')=='TCP']
    if len(matches)!=1:raise ValueError('one exact approved TCP port required')
    selected=matches[0];port=selected['nodePort']
    if type(port) is not int or not 30000<=port<=32767:raise ValueError('server allocation required')
    return ['http://'+('['+str(host)+']' if host.version==6 else str(host))+':'+str(port) for host in hosts]
